// Remove matching rows or columns of tiles, then let the remaining tiles fall down.
// match-grid: original MIT-licensed native educational port.
// Generated by tools/ports/generate.py; edit the specification to preserve parity.
// Input: [width,height,minimum_run,...tiles]
// Output: [matched_count,...collapsed_tiles]
// Tile -1 is empty. Detect horizontal/vertical matches, merge intersections, then apply column
// gravity. No random refill or cascade.
// Precondition: finite, correctly shaped data; integer indices/counts/IDs.
// See ../PORTS.md for examples, limits, and the shared test fixtures.

#![allow(unused_assignments, unused_mut, dead_code, unused_parens)]
// Count how many numbers are in this list.
fn port_length(a: &[f64]) -> f64 { a.len() as f64 }
// Read one number at a zero-based position; stop if that position does not exist.
fn port_get(a: &[f64], i:f64) -> f64 { assert!(i.is_finite() && i>=0.0 && i.fract()==0.0 && i<(a.len() as f64)); a[i as usize] }
// Replace a number at an existing position in the list.
fn port_put(i:f64, v:f64, a: &mut Vec<f64>) { port_get(a,i); a[i as usize]=v; }
// Add one number to the end of the list.
fn port_push(v:f64, a: &mut Vec<f64>) { a.push(v); }

// 1. Find long enough runs of identical nonempty tiles.
// 2. Mark each matching tile once, even where a row and column cross.
// 3. Remove all marked tiles together.
// 4. Slide surviving tiles to the bottom of each column without changing their order.
pub fn compute(data: &[f64]) -> Vec<f64> {
    let mut w: f64 = 0.0;
    let mut h: f64 = 0.0;
    let mut minimum_run: f64 = 0.0;
    let mut matched: Vec<f64> = Vec::new();
    let mut i: f64 = 0.0;
    let mut axis: f64 = 0.0;
    let mut count: f64 = 0.0;
    let mut grid: Vec<f64> = Vec::new();
    let mut x: f64 = 0.0;
    let mut result: Vec<f64> = Vec::new();
    let mut lines: f64 = 0.0;
    let mut span: f64 = 0.0;
    let mut line: f64 = 0.0;
    let mut bottom: f64 = 0.0;
    let mut y: f64 = 0.0;
    let mut start: f64 = 0.0;
    let mut cell: f64 = 0.0;
    let mut stride: f64 = 0.0;
    let mut tile: f64 = 0.0;
    let mut end_index: f64 = 0.0;
    let mut j: f64 = 0.0;
    w = port_get(&data, 0.0);
    h = port_get(&data, 1.0);
    minimum_run = port_get(&data, 2.0);
    if ((w < 1.0) || (h < 1.0) || (minimum_run < 2.0) || (port_length(&data) != (3.0 + (w * h)))) {
        return vec![-(1.0)];
    }
    matched = vec![];
    i = 0.0;
    while (i < (w * h)) {
        port_push(0.0, &mut matched);
        i += 1.0;
    }
    axis = 0.0;
    while (axis < 2.0) {
        lines = h;
        span = w;
        if (axis == 1.0) {
            lines = w;
            span = h;
        }
        line = 0.0;
        while (line < lines) {
            start = 0.0;
            while (start < span) {
                cell = ((line * w) + start);
                stride = 1.0;
                if (axis == 1.0) {
                    cell = ((start * w) + line);
                    stride = w;
                }
                tile = port_get(&data, (3.0 + cell));
                end_index = (start + 1.0);
                while ((end_index < span) && (port_get(&data, ((3.0 + cell) + ((end_index - start) * stride))) == tile)) {
                    end_index += 1.0;
                }
                if ((tile != -(1.0)) && ((end_index - start) >= minimum_run)) {
                    j = start;
                    while (j < end_index) {
                        port_put((cell + ((j - start) * stride)), 1.0, &mut matched);
                        j += 1.0;
                    }
                }
                start = end_index;
            }
            line += 1.0;
        }
        axis += 1.0;
    }
    count = 0.0;
    grid = vec![];
    i = 0.0;
    while (i < (w * h)) {
        count += port_get(&matched, i);
        port_push(-(1.0), &mut grid);
        i += 1.0;
    }
    x = 0.0;
    while (x < w) {
        bottom = (h - 1.0);
        y = (h - 1.0);
        while (y >= 0.0) {
            cell = ((y * w) + x);
            if ((port_get(&matched, cell) == 0.0) && (port_get(&data, (3.0 + cell)) != -(1.0))) {
                port_put(((bottom * w) + x), port_get(&data, (3.0 + cell)), &mut grid);
                bottom -= 1.0;
            }
            y -= 1.0;
        }
        x += 1.0;
    }
    result = vec![count];
    i = 0.0;
    while (i < port_length(&grid)) {
        port_push(port_get(&grid, i), &mut result);
        i += 1.0;
    }
    return result;
}
